#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""UDS 27 Seed&Key 换算及 Windows x64 加解密 DLL 生成模块。"""

import base64
import os
import re
import struct
import tkinter as tk
from tkinter import ttk, filedialog, messagebox

ALGOS = [
    'AES-128 ECB',
    'AES-192 ECB',
    'AES-256 ECB',
    'AES-128 CBC (IV=00)',
    'DES ECB',
    '3DES ECB',
    'AES-128 CMAC',
]

ALGO_IDS = {name: index + 1 for index, name in enumerate(ALGOS)}
KEY_LEN = {
    'AES-128 ECB': 16,
    'AES-192 ECB': 24,
    'AES-256 ECB': 32,
    'AES-128 CBC (IV=00)': 16,
    'DES ECB': 8,
    '3DES ECB': 24,
    'AES-128 CMAC': 16,
}
CMAC_OUTPUT_MODES = {
    '完整 16 字节': 16,
    '前 8 字节': 8,
    '前 4 字节': 4,
}
CONFIG_MAGIC = bytes([
    0x53, 0x45, 0x45, 0x44, 0x4B, 0x45, 0x59, 0x43,
    0x46, 0x47, 0x32, 0x37, 0x30, 0x32, 0xA5, 0x5A,
])
DLL_TEMPLATE_B64 = ''


def clean_hex(text):
    value = ''.join(text.split()).upper()
    if value.startswith('0X'):
        value = value[2:]
    if not value or len(value) % 2 or any(c not in '0123456789ABCDEF' for c in value):
        raise ValueError('请输入偶数长度的十六进制数据')
    return value


def validate_key(key_hex, algo):
    key_hex = clean_hex(key_hex)
    expected = KEY_LEN[algo]
    if len(key_hex) != expected * 2:
        raise ValueError(f'{algo} 需要 {expected} 字节 Key（{expected * 2} 个十六进制字符）')
    return key_hex


def calc(seed_hex, key_hex, algo, cmac_output='完整 16 字节'):
    """计算 27 02 响应；Seed 可带 67 01 前缀，Key 不带前缀。"""
    seed_hex = clean_hex(seed_hex) if seed_hex.strip() or algo != 'AES-128 CMAC' else ''
    if seed_hex.startswith('6701'):
        seed_hex = seed_hex[4:]
    key_hex = validate_key(key_hex, algo)
    seed = bytes.fromhex(seed_hex)
    key = bytes.fromhex(key_hex)

    from Crypto.Cipher import AES, DES, DES3

    if algo == 'AES-128 CMAC':
        from Crypto.Hash import CMAC
        cmac = CMAC.new(key, ciphermod=AES)
        cmac.update(seed)
        result = cmac.digest()[:CMAC_OUTPUT_MODES[cmac_output]]
    else:
        if not seed:
            raise ValueError('Seed 不能为空')
        if algo.startswith('AES'):
            block_size = 16
            mode = AES.MODE_CBC if algo.startswith('AES-128 CBC') else AES.MODE_ECB
            kwargs = {'iv': bytes(16)} if mode == AES.MODE_CBC else {}
            cipher = AES.new(key, mode, **kwargs)
        else:
            block_size = 8
            cipher = DES3.new(key, DES3.MODE_ECB) if algo == '3DES ECB' else DES.new(key, DES.MODE_ECB)
        if len(seed) % block_size:
            raise ValueError(f'{algo} 的 Seed 长度必须是 {block_size} 字节的整数倍（不自动填充）')
        result = cipher.encrypt(seed)
    return '27 02 ' + ' '.join(f'{b:02X}' for b in result)


def generate_dll(path, algo, key_hex, cmac_output='完整 16 字节', decrypt=False):
    """将算法、CMAC 截断长度和 Key 写入预编译模板，生成 Windows x64 DLL。"""
    key_hex = validate_key(key_hex, algo)
    if decrypt and algo == 'AES-128 CMAC':
        raise ValueError('AES-CMAC 是单向消息认证算法，不支持解密 DLL')
    data = bytearray(base64.b64decode(DLL_TEMPLATE_B64))
    offset = data.find(CONFIG_MAGIC)
    if offset < 0 or data.count(CONFIG_MAGIC) != 1:
        raise RuntimeError('DLL 模板配置区校验失败')
    key = bytes.fromhex(key_hex)
    config = struct.pack('<II32s', ALGO_IDS[algo], CMAC_OUTPUT_MODES[cmac_output], key.ljust(32, b'\0'))
    data[offset + 16:offset + 56] = config
    with open(path, 'wb') as f:
        f.write(data)
    return path


class SeedKeyFrame(ttk.Frame):
    """可嵌入 Notebook 的 UDS 27 Seed&Key 页面。"""

    def __init__(self, parent):
        super().__init__(parent, padding=12)
        self.columnconfigure(1, weight=1)

        ttk.Label(self, text='算法:').grid(row=0, column=0, sticky='w', pady=5)
        self.var_algo = tk.StringVar(value=ALGOS[0])
        self.cmb_algo = ttk.Combobox(self, textvariable=self.var_algo, values=ALGOS,
                                     state='readonly', width=28)
        self.cmb_algo.grid(row=0, column=1, sticky='w', padx=8, pady=5)
        self.cmb_algo.bind('<<ComboboxSelected>>', self.on_algo_change)

        ttk.Label(self, text='CMAC 输出:').grid(row=0, column=2, sticky='e', padx=(30, 8))
        self.var_cmac_output = tk.StringVar(value='完整 16 字节')
        self.cmb_cmac_output = ttk.Combobox(self, textvariable=self.var_cmac_output,
                                            values=list(CMAC_OUTPUT_MODES), state='disabled', width=15)
        self.cmb_cmac_output.grid(row=0, column=3, sticky='w', pady=5)
        self.cmb_cmac_output.bind('<<ComboboxSelected>>', lambda _e: self.recalc())

        self.var_seed = tk.StringVar()
        self.var_key = tk.StringVar()
        self.var_out = tk.StringVar()
        self.var_status = tk.StringVar(value='AES-128 ECB：Key 16 字节，Seed 长度须为 16 字节整数倍')
        for row, label, variable in [(1, '67 01:', self.var_seed), (2, 'Key:', self.var_key), (3, '27 02:', self.var_out)]:
            ttk.Label(self, text=label).grid(row=row, column=0, sticky='w', pady=6)
            entry = ttk.Entry(self, textvariable=variable, font=('Consolas', 10))
            entry.grid(row=row, column=1, columnspan=3, sticky='ew', padx=8, pady=6)
            if row < 3:
                variable.trace_add('write', lambda *_args: self.recalc())

        buttons = ttk.Frame(self)
        buttons.grid(row=4, column=0, columnspan=4, sticky='w', pady=12)
        ttk.Button(buttons, text='复制结果', command=self.copy).pack(side='left', padx=(0, 8))
        ttk.Button(buttons, text='清空', command=self.clear).pack(side='left', padx=8)
        ttk.Button(buttons, text='生成加密DLL', command=lambda: self.generate(False)).pack(side='left', padx=(20, 8))
        self.btn_decrypt = ttk.Button(buttons, text='生成解密DLL', command=lambda: self.generate(True))
        self.btn_decrypt.pack(side='left', padx=8)

        ttk.Label(self, textvariable=self.var_status, foreground='#555', wraplength=820,
                  justify='left').grid(row=5, column=0, columnspan=4, sticky='w', pady=(0, 8))
        help_text = (
            '说明：67 01 框支持带前缀（67 01 XX XX ...）或不带前缀，支持空格或连写 hex；结果自动添加 27 02。\n'
            'AES-128 CMAC 使用 16 字节 Key，支持任意长度 Seed；其余算法不自动填充，Seed 须为块长度整数倍。\n'
            'DLL：Windows x64，Key 和算法内置。导出 int Encrypt/Decrypt(const uint8_t* in, int in_len, '
            'uint8_t* out, int out_len)，返回 0 成功；同时提供 EncryptData/DecryptData 别名。'
        )
        ttk.Label(self, text=help_text, foreground='#666', wraplength=820,
                  justify='left').grid(row=6, column=0, columnspan=4, sticky='w', pady=8)

    def on_algo_change(self, _event=None):
        algo = self.var_algo.get()
        is_cmac = algo == 'AES-128 CMAC'
        self.cmb_cmac_output.config(state='readonly' if is_cmac else 'disabled')
        self.btn_decrypt.config(state='disabled' if is_cmac else 'normal')
        block = '任意长度 Seed' if is_cmac else f'Seed 长度须为 {16 if algo.startswith("AES") else 8} 字节整数倍'
        self.var_status.set(f'{algo}：Key {KEY_LEN[algo]} 字节，{block}')
        self.recalc()

    def recalc(self, *_args):
        seed = self.var_seed.get().strip()
        key = self.var_key.get().strip()
        if not seed or not key:
            self.var_out.set('')
            return
        try:
            self.var_out.set(calc(seed, key, self.var_algo.get(), self.var_cmac_output.get()))
        except Exception:
            self.var_out.set('')

    def copy(self):
        value = self.var_out.get()
        if value:
            self.clipboard_clear()
            self.clipboard_append(value)
            self.update()

    def clear(self):
        self.var_seed.set('')
        self.var_key.set('')
        self.var_out.set('')

    def generate(self, decrypt):
        algo = self.var_algo.get()
        try:
            key = validate_key(self.var_key.get(), algo)
            if decrypt and algo == 'AES-128 CMAC':
                raise ValueError('AES-CMAC 不支持解密 DLL')
        except Exception as exc:
            messagebox.showwarning('无法生成 DLL', str(exc), parent=self)
            return
        safe_algo = re.sub(r'[^A-Za-z0-9]+', '_', algo).strip('_')
        mode = 'Decrypt' if decrypt else 'Encrypt'
        path = filedialog.asksaveasfilename(
            parent=self,
            title=f'生成{mode} DLL',
            defaultextension='.dll',
            initialfile=f'SeedKey_{safe_algo}_{mode}.dll',
            filetypes=[('Windows x64 DLL', '*.dll')],
        )
        if not path:
            return
        try:
            generate_dll(path, algo, key, self.var_cmac_output.get(), decrypt)
            messagebox.showinfo(
                '生成成功',
                f'已生成：{os.path.basename(path)}\n算法：{algo}\nKey：{key}\n'
                f'接口：{mode}(in, in_len, out, out_len)，返回 0 成功。',
                parent=self,
            )
        except Exception as exc:
            messagebox.showerror('生成失败', str(exc), parent=self)


def main():
    root = tk.Tk()
    root.title('SeedKey 计算工具（27 01 / 27 02）')
    root.geometry('820x430')
    frame = SeedKeyFrame(root)
    frame.pack(fill='both', expand=True)
    root.mainloop()


if __name__ == '__main__':
    main()
